import * as mongoose from 'mongoose';

export interface IContainModel extends mongoose.Types.Subdocument {
  text: string;
  domain: string;
}

export interface IEqualModel extends mongoose.Types.Subdocument {
  text: string;
  domain: string;
}

export interface ISettingModel extends mongoose.Document {
  name: string;
  contain: mongoose.Types.Array<IContainModel>;
  equal: mongoose.Types.Array<IEqualModel>;
  active: boolean;
}

const containSchema = new mongoose.Schema({
  text: String,
  domain: String
});

const equalSchema = new mongoose.Schema({
  text: String,
  domain: String
});

const settingSchema = new mongoose.Schema({
  name: String,
  contain: [containSchema],
  equal: [equalSchema],
  active: Boolean
}, {
  timestamps: true
});

const Setting = mongoose.model<ISettingModel>('Setting', settingSchema);

export default Setting;
